def build2(out, bits=64, endian='little', phdrs=None, shdrs=None, extra=b'', extend=True, fields=None):
    import struct as st
    le = endian=='little'; pre = '<' if le else '>'
    phdrs = phdrs or []; shdrs = shdrs or []
    ident = bytearray(16); ident[0:4]=b'\x7fELF'
    ident[4]=2 if bits==64 else 1; ident[5]=1 if le else 2; ident[6]=1
    eh=64 if bits==64 else 52; phes=56 if bits==64 else 32; shes=64 if bits==64 else 40
    phoff = eh if phdrs else 0
    shoff = eh + len(phdrs)*phes if shdrs else 0
    f = dict(e_type=2,e_machine=62,e_version=1,e_entry=0x1000,e_phoff=phoff,e_shoff=shoff,
             e_flags=0,e_ehsize=eh,e_phentsize=phes,e_phnum=len(phdrs),e_shentsize=shes,
             e_shnum=len(shdrs),e_shstrndx=0)
    if fields: f.update(fields)
    phoff=f['e_phoff']; shoff=f['e_shoff']; phes=f['e_phentsize']; shes=f['e_shentsize']
    if bits==64:
        ehdr = st.pack(pre+"HHIQQQIHHHHHH",f['e_type'],f['e_machine'],f['e_version'],f['e_entry'],phoff,shoff,f['e_flags'],f['e_ehsize'],phes,f['e_phnum'],shes,f['e_shnum'],f['e_shstrndx'])
        def ph(t,fl,off,va,pa,fs,ms,al): return st.pack(pre+"IIQQQQQQ",t,fl,off,va,pa,fs,ms,al)
        def sh(nm,t,fl,addr,off,sz,lk,inf,al,es): return st.pack(pre+"IIQQQQIIQQ",nm,t,fl,addr,off,sz,lk,inf,al,es)
    else:
        ehdr = st.pack(pre+"HHIIIIIHHHHHH",f['e_type'],f['e_machine'],f['e_version'],f['e_entry'],phoff,shoff,f['e_flags'],f['e_ehsize'],phes,f['e_phnum'],shes,f['e_shnum'],f['e_shstrndx'])
        def ph(t,off,va,pa,fs,ms,fl,al): return st.pack(pre+"IIIIIIII",t,off,va,pa,fs,ms,fl,al)
        def sh(nm,t,fl,addr,off,sz,lk,inf,al,es): return st.pack(pre+"IIIIIIIIII",nm,t,fl,addr,off,sz,lk,inf,al,es)
    php = st.pack(pre+'B',0)* (56 if bits==64 else 32)
    size = max(eh, phoff + len(phdrs)*phes if phdrs else 0, shoff + len(shdrs)*shes if shdrs else 0)
    end = size + len(extra)
    if extend:
        for p in phdrs:
            end = max(end, (p[2] if bits==64 else p[1]) + (p[5] if bits==64 else p[4]))
        for s in shdrs:
            if s[1] != 8: end = max(end, s[4]+s[5])
    buf = bytearray(end)
    buf[0:16]=ident; buf[16:16+len(ehdr)]=ehdr
    for i,p in enumerate(phdrs): buf[phoff+i*phes:phoff+i*phes+len(ph(*p))]=ph(*p)
    for i,s in enumerate(shdrs): buf[shoff+i*shes:shoff+i*shes+len(sh(*s))]=sh(*s)
    buf[size:size+len(extra)] = extra
    open(out,'wb').write(bytes(buf))
